#include <iostream>
#include <string>
using namespace std;

int main() {
    int n, k;
    string s;
    cin >> n >> k >> s;

    if (n == 1) {
        if (k > 0) s[0] = '0';
        cout << s;
        return 0;
    }

    if (k > 0 && s[0] != '1') {
        s[0] = '1';
        --k;
    }

    for (int i = 1; i < n && k > 0; ++i) {
        if (s[i] != '0') {
            s[i] = '0';
            --k;
        }
    }

    cout << s;
    return 0;
}

